    net = sum(forces)
    return {"action": "EQUILIBRIUM" if abs(net) < 1e-6 else "UNBALANCED",
            "intensity": 0.5, "version": 1,
            "result": {"net_force_n": round(net, 6), "count": len(forces)}}

def skill(organism, context):
