    lam = float(context.get("wavelength_m", 0))
    c = f * lam
    return {"action": "WAVE_SPEED", "intensity": 0.5, "version": 1,
            "result": {"speed_m_s": round(c, 4),
                       "frequency_hz": f,
                       "wavelength_m": lam}}
